import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Настройка канала Telegram","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/telegram.md","filePath":"ru/integrations/channels/telegram.md","lastUpdated":1792323081000}'),l={name:"ru/integrations/channels/telegram.md"};function n(i,e,s,h,d,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="настроика-канала-telegram" tabindex="-1">Настройка канала Telegram <a class="header-anchor" href="#настроика-канала-telegram" aria-label="Permalink to &quot;Настройка канала Telegram&quot;">​</a></h1><p>Подключите своего Bot в Memoh к Telegram — это один из наиболее полно поддерживаемых каналов в Memoh: потоковые ответы, форматирование Markdown и вложения.</p><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>Аккаунт Telegram; Bot создаётся в переписке с <strong>@BotFather</strong>.</li><li>Bot в Memoh; каналы настраиваются на его вкладке <strong>Platforms</strong>.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-в-telegram-создаите-bot-через-botfather" tabindex="-1">1. В Telegram создайте Bot через @BotFather <a class="header-anchor" href="#_1-в-telegram-создаите-bot-через-botfather" aria-label="Permalink to &quot;1. В Telegram создайте Bot через @BotFather&quot;">​</a></h3><ol><li>Откройте Telegram и найдите официального <strong>@BotFather</strong>.</li><li>Отправьте команду <code>/newbot</code>.</li><li>Следуйте подсказкам: <ul><li><strong>Name</strong>: отображаемое имя вашего Bot (например, <code>My Memoh Bot</code>).</li><li><strong>Username</strong>: уникальное имя пользователя, оканчивающееся на <code>bot</code> (например, <code>my_memoh_bot</code>).</li></ul></li><li>BotFather ответит сообщением с <strong>API Token</strong> (например, <code>123456789:ABCdefGHIjklMNOpqrsTUVwxyz</code>). <strong>Держите этот токен в секрете.</strong></li></ol><blockquote><p>Официальное руководство: <a href="https://core.telegram.org/bots/tutorial" target="_blank" rel="noreferrer">Telegram Bot Tutorial</a></p></blockquote><h3 id="_2-в-memoh-добавьте-канал-telegram" tabindex="-1">2. В Memoh добавьте канал Telegram <a class="header-anchor" href="#_2-в-memoh-добавьте-канал-telegram" aria-label="Permalink to &quot;2. В Memoh добавьте канал Telegram&quot;">​</a></h3><ol><li>Откройте страницу нужного Bot и выберите вкладку <strong>Platforms</strong>.</li><li>Нажмите <strong>Add Channel</strong> и выберите <strong>Telegram</strong>.</li><li>Вставьте <strong>API Token</strong> в поле учётных данных.</li><li>Нажмите <strong>Save and Enable</strong>.</li></ol><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>API Token</strong></td><td>Токен, который BotFather выдаёт при создании Bot (например, <code>123456789:ABC...</code>). Держите его в секрете.</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Откройте личный чат с Bot в Telegram и отправьте <code>/help</code>. Если Bot ответил списком команд, канал работает.</p><h2 id="групповые-чаты" tabindex="-1">Групповые чаты <a class="header-anchor" href="#групповые-чаты" aria-label="Permalink to &quot;Групповые чаты&quot;">​</a></h2><p>Групповые чаты Telegram поддерживаются. Добавьте Bot в группу и обращайтесь к нему через @-упоминание по имени пользователя.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить этот канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить токен, обновите поле <strong>API Token</strong> и сохраните.</p>',18)])])}const b=t(l,[["render",n]]);export{c as __pageData,b as default};
